}
/** O nível que a missão dá. 12/11/2026, livro R66: "no máximo um nível por missão concluída". `teto` é o nível até
 *  onde a edição pode subir (o atual mais as missões que ela tocou); abaixo da curva, a primeira linha dela. */
function salarioNivelQueSobe_(tabela,xp,atual,limiar,teto){
 var alvo=null;tabela.forEach(function(l){if(Number(l.xp)<=xp)alvo=Number(l.nivel);});
 if(alvo===null)return null;if(limiar&&atual<=limiar)alvo=Math.min(alvo,limiar);
 if(teto!==undefined&&teto!==null&&tabela.length)alvo=Math.min(alvo,Math.max(teto,Number(tabela[0].nivel)));
 return alvo>atual?alvo:null;
}
/** 12/11/2026: quantas missões a edição conta para subir o nível, uma por caixa cujo nome ou tipo ela tocou. O adicional
 *  e o desconto sozinhos não contam: o XP a mais fica guardado até a próxima missão, como manda o livro. Na edição de
 *  uma célula só, a caixa conta; colando várias linhas, só as que ficaram com tipo. */
function salarioMissoesDaEdicao_(l1,l2,c1,c2,sh){
 l1=Math.max(l1,SALARIO_.primeira);l2=Math.min(l2,SALARIO_.ultima);if(l1>l2)return 0;
 var cols=SALARIO_.colunas.filter(function(c){return (c>=c1&&c<=c2)||(c+1>=c1&&c+1<=c2);});
 if(!cols.length)return 0;if(l1===l2&&cols.length===1)return 1;
 var v=sh.getRange(l1,49,l2-l1+1,24).getValues(),n=0;
 cols.forEach(function(c){for(var i=0;i<v.length;i++)if(SALARIO_.tipos.indexOf(String(v[i][c+1-49]||'').trim())>=0)n++;});
 return n;
}
